        public static string Get(string key)
        {
            if (_t.TryGetValue(key, out var row))
            {
                if (row.TryGetValue(Current, out var val)) return val;
                if (row.TryGetValue("en",    out var fallback)) return fallback;
            }
            return key; // return key as-is if missing
        }

        public static event Action? LanguageChanged;

        public static void SetLanguage(string langCode)
        {
            Current = langCode.ToLowerInvariant();
            LanguageChanged?.Invoke();
        }
    }
